export class GraphRAGConflictResolver {
  constructor() {
    this.knowledgeGraph = new Map();
  }

  addAgentOutput(agentId, output, confidence) {
    // Add outputs in the knowledge graph
    this.knowledgeGraph.set(agentId, { output, confidence });
  }

  resolveConflicts() {
    // Apply weighted confidence voting to resolve conflicts
    const aggregatedResults = {};
    this.knowledgeGraph.forEach((value, agentId) => {
      const { output, confidence } = value;
      if (!aggregatedResults[output]) {
        aggregatedResults[output] = 0;
      }
      aggregatedResults[output] += confidence;
    });

    // Return the output with the highest aggregated confidence
    return Object.entries(aggregatedResults).sort((a, b) => b[1] - a[1])[0][0];
  }
}
